    16		const queue = new Queue();
    17		let activeCount = 0;
    18	
    19		const resumeNext = () => {
    20			// Process the next queued function if we're under the concurrency limit
    21			if (activeCount < concurrency && queue.size > 0) {
    22				activeCount++;
    23				queue.dequeue().run();
    24			}
    25		};
    26	
    27		const next = () => {
    28			activeCount--;
    29			resumeNext();
    30		};
    31	
    32		const run = async (function_, resolve, arguments_) => {
    33			// Execute the function and capture the result promise
    34			const result = (async () => function_(...arguments_))();
    35	
    36			// Resolve immediately with the promise (don't wait for completion)
    37			resolve(result);
    38	
    39			// Wait for the function to complete (success or failure)
    40			// We catch errors here to prevent unhandled rejections,
    41			// but the original promise rejection is preserved for the caller
    42			try {
    43				await result;
    44			} catch {}
    45	
    46			// Decrement active count and process next queued function
    47			next();
    48		};
    49	
    50		const enqueue = (function_, resolve, reject, arguments_) => {
    51			const queueItem = {reject};
    52	
    53			// Queue the internal resolve function instead of the run function
    54			// to preserve the asynchronous execution context.
    55			new Promise(internalResolve => { // eslint-disable-line promise/param-names
